#!/usr/bin/env python3
import argparse,hashlib,json
from pathlib import Path

def load(path): return json.loads(path.read_text())
def digest(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def main():
    p=argparse.ArgumentParser();p.add_argument("--dataset",type=Path,required=True);p.add_argument("--qc",type=Path,required=True);p.add_argument("--statistics",type=Path,required=True);p.add_argument("--dtu",type=Path,required=True);p.add_argument("--splicing",type=Path,required=True);p.add_argument("--ends",type=Path,required=True);p.add_argument("--orfs",type=Path,required=True);p.add_argument("--switches",type=Path,required=True);p.add_argument("--enrichment",type=Path,required=True);p.add_argument("--integrated",type=Path,required=True);p.add_argument("--output",type=Path,required=True);a=p.parse_args()
    statuses={"design":load(a.dataset/"design_status.json"),"expression_qc":load(a.qc/"expression_qc_status.json"),"gene_differential_expression":load(a.statistics/"genes.status.json"),"transcript_differential_expression":load(a.statistics/"transcripts.status.json"),"differential_transcript_usage":load(a.dtu/"dtu_status.json"),"splicing_events":load(a.splicing/"events"/"events_status.json"),"psi":load(a.splicing/"psi"/"psi_status.json"),"differential_splicing":load(a.splicing/"differential"/"differential_status.json"),"transcript_ends":load(a.ends/"transcript_ends_status.json"),"orfs":load(a.orfs/"orf_status.json"),"isoform_switches":load(a.switches/"isoform_switch_status.json"),"enrichment":load(a.enrichment/"enrichment_status.json"),"integrated":load(a.integrated/"integrated_status.json")}
    paths={"gene_count_matrix":"biology/abundance/gene_counts.tsv","transcript_count_matrix":"biology/abundance/transcript_counts.tsv","gene_abundance_matrix":"biology/abundance/gene_tpm.tsv","transcript_abundance_matrix":"biology/abundance/transcript_tpm.tsv","transcript_id_map":"biology/abundance/transcript_id_map.tsv","sample_design":"biology/abundance/sample_metadata.tsv","design_status":"biology/abundance/design_status.json","gene_differential_expression":"biology/differential_expression/genes.differential_expression.tsv","gene_filtering":"biology/differential_expression/genes.filtering.tsv","transcript_differential_expression":"biology/differential_expression/transcripts.differential_expression.tsv","transcript_filtering":"biology/differential_expression/transcripts.filtering.tsv","dtu":"biology/transcript_usage/dtu_results.tsv","dtu_filtering":"biology/transcript_usage/dtu_filtering.tsv","splicing_events":"biology/alternative_splicing/events/events.tsv","psi":"biology/alternative_splicing/psi/psi.tsv","differential_splicing":"biology/alternative_splicing/differential/differential_splicing.tsv","transcript_ends":"biology/transcript_ends/transcript_boundaries.tsv","orfs":"biology/orfs/orf_predictions.tsv","isoform_switches":"biology/isoform_switches/isoform_switches.tsv","enrichment":"biology/enrichment/go_enrichment.tsv","integrated":"biology/integrated/integrated_biology.tsv"}
    versions={}
    for directory in (a.statistics,a.dtu,a.switches,a.enrichment):
        v=directory/"versions.json"
        if v.exists():versions[v.parent.name]=load(v)
    for name,directory in (("SUPPA",a.splicing),("TransDecoder",a.orfs)):
        v=directory/"runtime_versions.json"
        if v.exists(): versions[name]=load(v)
    contract={"contract_version":"4.0","production_transcriptome":"IsoQuant via Block 2 standardized transcriptome contract","benchmark_callers_used_to_define_transcriptome":False,"paths":paths,"analysis_status":statuses,"runtime_versions":versions,"evidence_hierarchy":{"observed":["reads","transcript structure","abundance","splice junctions"],"statistically_inferred":["differential expression","DTU","differential splicing","isoform switching"],"computationally_predicted":["ORFs","coding consequences","domains","NMD-related consequences","enrichment"],"experimentally_validated":[]},"rna_modification_calling":"OUTSIDE_V1","block5_started":False,"checksums":{"integrated_biology_sha256":digest(a.integrated/"integrated_biology.tsv")}}
    a.output.write_text(json.dumps(contract,indent=2)+"\n")
if __name__=="__main__":main()
